quests[92722] = { id = 92722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Story of Russula's Outreach", description = "The spear still waits where you last left it, pale threads of mushroom slowly weaving new patterns into its grain.\n\nThe culling grounds draw you again. Walk their softened paths, follow what spores still rise, and let the visions show what time has chosen to reveal this season.", sourceObjective = "Travel to the Verdant Sepulcher to learn the history of Russula's Outreach.", progress = "What shape did the tale take this time? Tell me, and we will fold this telling into the many before it.", completion = "You have tended the memory well, {name}.\n\nTake this token of thanks. When the land calls -- as it always does -- return. Even mercy has layers yet to be uncovered.", sourceObjectiveStatus = "unverified-source-field" }
quests[92724] = { id = 92724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Story of the Root of the World", description = "The Root of the World stands as it did before--ancient, unbowed--yet the soil breathes differently today. Beneath your feet, the pulse of Harandar quickens, as though eager to share another verse of its oldest story.\n\nYou have seen through Ruilla the Huntress's eyes once before. But the Rootways are never walked the same way twice. Go again, and let the land decide which truths it will show you now.", sourceObjective = "Travel to the Vale of Secrets to learn the history of the Root of the World.", progress = "And so the Root yielded another fragment? Tell me, what shade of truth did it whisper this time?", completion = "Once more the Root speaks through Ruilla's memory, and once more the lesson comes wrapped in both pride and sorrow. She remains the first Rootwarden, the first to walk those hidden ways, but fresh details now cling to her legend like moss to stone.\n\nYour return is a gift to the land as much as to me, {name}. When the soil shifts again beneath your steps, we will listen together.", sourceObjectiveStatus = "unverified-source-field" }
quests[92725] = { id = 92725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Story of Sky's Hope", description = "Sky's Hope rests in its cradle as before, yet the heavens above seem sharper tonight.\n\nYou have traced Awe'ohna's path once, but the tale shifts with every telling. Walk the path again, and perhaps the sky will tilt just so, revealing a truth you missed before.", sourceObjective = "Travel to the Shrouded Grove in Harandar to learn the history of Sky's Hope.", completion = "Again the sky has turned in your favor, {name}, and again Awe'ohna's story greets you with both clarity and mystery.\n\nWhen the firmament stirs once more, I trust you'll be ready to walk under it with me again.", sourceObjectiveStatus = "unverified-source-field" }
quests[92728] = { id = 92728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dogged Disturbances", description = "That dog! It ran through here and disrupted every lesson on the schedule. Now there are fire elementals everywhere and my students are ill-prepared to handle this mess. How am I supposed to teach in all of this chaos?\n\nYou look capable--would you clear out some of these rowdy little elementals? The sooner we get this situation under control, the better!", progress = "Have you gotten those rowdy little sparks under control?", completion = "Thank you for your assistance! My students should be able to handle the rest of them after a few quick lessons. We'll just call this a learning opportunity.", objectives = "Kill 8 Rowdy Elementals in Thalassian University.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92729] = { id = 92729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hounded and Hassled", description = "Gilneas and Kul Tiras are both known for their hunting hounds. With the resurgence of elfhounds in Silvermoon, I thought perhaps they could be similarly utilized. They're dogs, after all. How hard could training possibly be?\n\nLong story short, that dog made a mess and dashed off. I have to clean this up. \n\nWould you please find that creature and bring him back to me before the local canine cafe has my head? I only borrowed him for the day!", completion = "A dog? Yes I've seen a dog--look at this place! Just look at what he's done!", objectives = "Speak to Magistrix Zaedana in Thalassian University.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92731] = { id = 92731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artificing Aggression", sourceObjective = "Craft a blade with Decimus.", sourceObjectiveStatus = "unverified-source-field" }
quests[92732] = { id = 92732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Disturbance", description = "We have had victories against the Lightbloom, but Alndust is rare. Until we can gather more, the Lightbloom continues its spread. Our forces are stretched too thin to watch their every movement.\n\nA scout spotted a strange corpse by the road to the east, along with a report of a general disturbance of the light-cursed creatures. I can't look into both at once. Could you find that corpse while I investigate deeper into the Encroaching Bloom?", completion = "<This corpse appears to be covered with Lightbloom spores and was fighting recently. It must be what the scout saw.>", objectives = "Go to the disturbance Hannan's scout found.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92736] = { id = 92736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Stroll", description = "<These potatoad creatures are seldom seen near the Lightbloom. It is covered in spores and looks like it was trying to escape. You should search for more clues.>", completion = "This herd was seized recently--the signs you discovered make that clear. This encroachment is pressing into untainted lands, and the herds could be depleted beyond recovery.\n\nI appreciate your help, but there is more that must be done.", objectives = "Search for clues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92737] = { id = 92737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Carnage", description = "The Lightbloom has infected many of these potatoads and spurred them into a frenzy. They spread the spores and reproduce at a dangerous rate.\n\nIf we don't act, we will be overrun. Will you cull this heard while I search for the source of the corruption?", progress = "We must protect Harandar's natural species from this invasive growth.", completion = "It is a shame to destroy the creatures of Harandar, but sometimes it must be done to protect the land.", objectives = "Kill 12 Lightfrenzied Potatoads.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92738] = { id = 92738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Potatoad Tots", description = "It is too late for the adults, but the young may still be saved. If you can capture them, we can remove the spores before they take root.\n\nGather up the spore covered potadpoles and bring them to me. I will take them to Har'alnor myself to purge this Lightbloom.\n\nDo not let their first breaths be their last. Please, {name}: save the babies.", completion = "You have saved so many. The balance of the land may still stand thanks to your efforts.", objectives = "Collect 8 Lightspored Potadpoles and bring them to Hannan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92739] = { id = 92739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "O.K. Bloomer", description = "I have discovered the lair of a cunning creature I call Adzikel. With luck, this name will soon be forgotten. \n\nAdzikel sneaks into the potatoad nests to steal their young, and plants the Lightbloom spores to accelerate their growth into the frenzied toads, which spread more spores.\n\nFor the little ones to have a chance, I must return to Har'alnor, but you have earned the right to slay this beast. Go with honor, and finish the hunt!", completion = "The Lightbloom is persistent, but so are you. Aln'hara's lands and creatures remain thanks to your efforts.\n\nThe young are being restored to their natural habitat, freed of the spores--all of them except this one. It is too small for the wild.\n\nIt will need a caregiver, and I think it has bonded to you.", objectives = "Kill the creature spreading these spores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92740] = { id = 92740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Questionable Qualifications", description = "Well {class}, it's your lucky day. I just happen to have an extremely genuine Brawler's Guild Invitation right here in my stockpile.\n\nThat said I'll need a moment to process the paperwork. That requires my complete concentration without your prying eyes on me. So do please give me a moment.", progress = "Here's your extremely genuine Brawler's Guild Invitation.\n\nPlease note all sales are final.\n\nThere will be no refunds, or receipts.", completion = "Some of the lines look a little crooked.", objectives = "Purchase an extremely genuine Brawler's Guild Invitation from Alton Philips.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92746] = { id = 92746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twist of the Stormfields", objectives = "Craft a blade with Decimus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
