quests[92816] = { id = 92816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Letter for Adventure", description = "<You look down to see a rough looking letter with your name on it.\n\nWhy not open it up to see what's inside?>", objectives = "Open the Adventuring Letter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92821] = { id = 92821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ignite the Skies: Silvermoon", description = "The season of Midsummer is celebrated by many cultures across Azeroth.\n\nEven now, bonfires across the land are ignited in honor of the spirits of fire.\n\nTo share our customs with all who dwell under the sun's warmth, I've had crates of sun blossoms brought to Silvermoon.\n\nTake to the skies and ignite the blossoms above, {name}!", sourceObjective = "Ignite the skies by flying through the sun blossoms over Silvermoon.", completion = "The citizens of Silvermoon were quite enthused by your aerial display over the city.\n\nEven the dragonhawks seemed to enjoy the glow of the blossoms overhead.\n\nThank you for bringing joy to so many during this summer festival.\n\nThe spirits of fire and An'she himself will be pleased.", sourceObjectiveStatus = "unverified-source-field" }
quests[92826] = { id = 92826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lorewalking: The Loa of Kings", description = "Where to begin? There's so much to say!\n\nThere's a great story from the Zandalari about the connection between troll and loa. Let's start there!", sourceObjective = "Follow Li Li's guidance to learn about the loa.", completion = "With Rezan defeated, King Rastakhan was in big trouble. He was wounded far deeper than any physical strike, as his connection to health and longevity were both ripped away.", sourceObjectiveStatus = "unverified-source-field" }
quests[92829] = { id = 92829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lorewalking: Death of the Drakkari Loa", description = "The Drakkari of Zul'Drak are well known for massacring their loa. The prophets of the Drakkari loa decided to take the full power of the loa by force.\n\nThe loa were blind-sided by this betrayal. They never dreamed rituals existed that could permanently kill them and steal their essence.", sourceObjective = "Follow Li Li's guidance to learn about the Drakkari.", completion = "The Drakkari empire crumbled after Gundrak fell. It couldn't recover from the turn into darkness and the aftermath that followed.", sourceObjectiveStatus = "unverified-source-field" }
quests[92831] = { id = 92831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lorewalking: The Blood Loa", description = "Not every loa is a protector and companion to trolls. There are loa that eat their followers, like the blood loa, Hakkar. In trade for sacrifices, Hakkar grants dark blood powers to his followers. But he always takes more than he gives.\n\nHakkar the Soulflayer has absorbed so much blood from his cultists that he's become almost a perpetual threat to the world.", sourceObjective = "Follow Li Li's guidance to learn about Hakkar.", sourceObjectiveStatus = "unverified-source-field" }
quests[92832] = { id = 92832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lorewalking: The Hash'ey", description = "The last story I want to share is about the Darkspear trolls... and Mueh'zala.\n\nMueh'zala is a mighty Loa of Death. Highly manipulative, he puts his plans into motion by using others as his pawns.\n\nHe's used a hash'ey in the past. A hash'ey is a troll imbued with the full power of the loa.", sourceObjective = "Follow Li Li's guidance to learn about Mueh'zala.", completion = "Both loa and troll have tried to force the bond of the hash'ey, but the strongest bonds are when they work together.\n\nThere's so much to learn about the loa. I'm still collecting their stories, but this was a good start!", sourceObjectiveStatus = "unverified-source-field" }
quests[92836] = { id = 92836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reignite the Skies: Stormwind", description = "Welcome to the Midsummer Festival of Fire, friend! \n\nHave you come to toss a few torches? Or maybe dance around the maypole?\n\nAh, you must be here to ignite the blossom lights over the skies of Stormwind, aren't you? It is an old tradition, long forgotten but newly rekindled!\n\nWell, come on then, take to the skies and fly!", sourceObjective = "Ignite the skies by flying through the blossoms over Stormwind.", completion = "It warms me to see the blossoms take to the sky once more.\n\nStormwind is not the only place you'll see this tradition taking place, of course.\n\nAll over the Eastern Kingdoms, blossom lights are floating upwards, waiting to be ignited!", sourceObjectiveStatus = "unverified-source-field" }
quests[92839] = { id = 92839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reignite the Skies: Orgrimmar", description = "Midsummer is a time to reflect on the past and future. As old traditions fade, new traditions are born. \n\nOne old tradition, practiced long ago, involved the offering of sun blossoms to An'she. As summer winds took them upwards, the blossoms would burn bright blue and orange.\n\nBut faded traditions need not remain lost.\n\n\nWill you take to the skies to ignite the sun blossoms and help rekindle this old tradition?", sourceObjective = "Ignite the skies by flying through the sun blossoms over Orgrimmar.", completion = "You have done our festival a great honor.\n\nIt has been many generations since the skies above have been filled with Sun blossoms.\n\nBut our celebrations need not be restricted to just the skies of Orgrimmar. All of Kalimdor awaits!", sourceObjectiveStatus = "unverified-source-field" }
quests[92845] = { id = 92845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By Invitation Only?", description = "Fancy yourself a Brawlpub contender do you, {class}? They don't let just anyone in there, you know. Certainly not without an invitation.\n\nThat said... just between you and me, if you know where to look and you've the means they say anyone can have their moment in the spotlight these days.", completion = "Looking for a Brawler's Guild invitation are you?\n\nVery hard to come by those, or expensive, or both!\n\nBut maybe you and I can work out a deal.", objectives = "Talk to Pick Butterworth near Bizmo's Brawlpub in the Deeprun Tram.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92848] = { id = 92848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: The Grand Magister's Drink" }
quests[92851] = { id = 92851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Questionable Qualifications", description = "Well {class}, it's your lucky day. I just happen to have an extremely genuine Brawler's Guild Invitation right here in my stockpile.\n\nThat said I'll need a moment to process the paperwork. That requires my complete concentration without your prying eyes on me. So do please give me a moment.", progress = "Here's your extremely genuine Brawler's Guild Invitation.\n\nPlease note all sales are final.\n\nThere will be no refunds, or receipts.", completion = "Some of the lines look a little crooked.", objectives = "Purchase an extremely genuine Brawler's Guild Invitation from Pick Butterworth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92855] = { id = 92855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Haste, Not Waste", objectives = "What, you think I'm just going to give you my crafts for free?\n\n<Lidamorrutu grumbles.>\n\nI suppose that's exactly what I'm going to do. Eternus's orders, something about speeding up the experiment.\n\nJust don't lose it or, worse, let Erus anywhere near it.You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92857] = { id = 92857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ta'readon's Mount Voucher", description = "This token bears the seal of Overseer Ta'readon in Oribos. They would be interested in seeing this.", completion = "I see you have served our merchants admirably. Accept one of our finest steeds as a reward.", objectives = "Bring Ta'readon's Mount Voucher to Overseer Ta'readon in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92864] = { id = 92864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drift Them Away", description = "With the hydras hunted out of the area, the drifter population in the cascades to the west is on the rise. Egg sacks are making the water murky and undrinkable, and the drifters are becoming very territorial.\n\nWe must ensure that the reintroduction of the hydras will succeed. We need to cull the number of drifters and clear some of their egg sacks.\n\nYou look like someone capable of doing this task. Will you help me?", completion = "It pains me to cull the drifter population. However, if left unchecked, their numbers would have led to the collapse of the ecosystem.", objectives = "Slay 8 Cascade Drifters and remove 5 Drifter Egg Sacks from the cascades at Nordrassil Roots.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92865] = { id = 92865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeding the Buds", description = "The orchid hydra's favorite food is the violet chloroceros--especially the buds on the bull's back.\n\nWith the hydras gone for so long, the violet chloroceros grazed too much of the fauna. Soon, there will only be mud in that once lush and beautiful part of Harandar.\n\nI want to introduce my hydras to their primary source of food, and I would appreciate it if you could bring me four of those buds.", progress = "The precious budlings will be very happy with their first taste of the chloroceros buds.", completion = "The budlings seem to be satiated for now. I am comfortable moving to the second phase of reintroducing them to their natural habitat.", objectives = "Collect 4 Chloroceros Buds from the Violet Chloroceros, then feed them to the Hydra Budlings in Har'athir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92866] = { id = 92866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Re-Hydra-ted", description = "With the previous tasks done, it is time to reintroduce the budlings to the wilds.\n\nI have marked suitable locations to place the budlings. The little hydras will be an easy pick, so expect predators to attack you.\n\nI am sad to see them go. However, I know it is for the ecosystem's and their own good.", completion = "You are back, and the feeling is bittersweet. On one hand, I have lost my babies, but on the other, I know it is for the best. I could go and visit them... or maybe I shouldn't, considering they would be unruly and four times my size.\n\nRegardless, thank you for your help. I will never forget this kindness.", objectives = "Place the budlings in the marked areas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92868] = { id = 92868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He Went Thataway", description = "You've been invaluable, {name}. As for that little menace, after he was done wreaking havoc here, I didn't really pay attention to where he went next. I'm sure you'll find him eventually. \n\nLet's hope you do before he wrecks half the city, hmm?", completion = "A dog? Yes I've seen a dog, just look at what that monster's done to the pond!", objectives = "Speak to Drathen in the Bazaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92869] = { id = 92869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fishy Dis-pondencies", description = "That dog tore right through the pond and sent half the sunwhiskers flying right out of the water! Quickly, get them back in the pond before they perish!", progress = "Hurry! They're terribly delicate creatures!", completion = "Your methods were... interesting, but I cannot deny the results. The sunwhiskers may be a little shaken up, but they'll recover soon enough now that they're back in the water where they belong. My thanks.", objectives = "Return 8 Coy Sunwhisker to the pond in the Bazaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92870] = { id = 92870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scoot Along Now", description = "That dog! The last I saw he was tearing through the pond. I didn't see where he went, but he has to be nearby!\n\nHis barks... they haunt me...", completion = "Lil' Scoots! Welcome back, you fuzzy menace. Thank you, champion. I'll return him to the cafe posthaste.\n\nAs for training... I think I shall stick to the local lynx. Far better manners.", objectives = "Catch Lil' Scoots and return him to Ranger Telenus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92875] = { id = 92875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Understanding the War Within", description = "I fear your time in Valdrakken must come to an end.\n\nDark forces gather to threaten other parts of Azeroth. We will do what we can to uncover Iridikron's schemes.\n\nYou must learn more of what has unfolded.", completion = "<The tome floats in front of you. Its pages are filled with knowledge of all that has happened.>", objectives = "Consult the Tome of History within Valdrakken to learn about the War Within saga.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92882] = { id = 92882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hunter's Plight", description = "I am desperate enough to ask an outsider for help.\n\nTo join the Ka'dani, the elite hunters of Har'athir, you must complete a ritual under the guidance of an experienced Ka'dani. However, there are none left to guide me, so I cannot take the trial.\n\nBut I have heard words of your actions. Maybe Akazi, the Ka'dani Elder, would let you stand as my guide. You may not know the ritual, but you know the hunt.\n\nPlease, let us speak to Elder Akazi. We must try.", progress = "Ketan tells me that you wish to mentor him. Is this true?", completion = "I will give you my blessing, {name}. Although you are not a Ka'dani, tales of your prowess precede you. Your skills in the hunt need no introduction.\n\nI know that you will be able to give Ketan the guidance he needs.\n\nYou will both take part in the Ka'dani trials: you as an honorary Ka'dani, and Ketan as your trainee.", objectives = "Ketan wants you to talk to Elder Akazi about the Ka'dani trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92883] = { id = 92883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hunter's Duty", description = "At the start of the trial, the mentor and trainee gather materials to forge a hunting weapon.\n\nThe weapon is more than an extension of the Ka'dani-- it's part of their being. There is no other weapon like it, as each is unique.\n\nYou will help Ketan hunt and gather the materials and decorations, as well as a gift for the weaponsmith.", progress = "Were you able to get everything? I know some of the required materials can be hard to gather.", completion = "These look pristine.\n\nThank you for doing this for me. Maybe one day I will be able to do the same for someone else.", objectives = "Hunt down beasts around Har'athir and collect materials to forge a Ka'dani weapon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92884] = { id = 92884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hunter's Weapon", description = "Forging the Ka'dani weapon is a crucial moment in the trial. We will have to follow Al'yaat's instructions.\n\nOnce Al'yaat forges the weapon, you will bring it to Elder Akazi.\n\nThere will be a short ceremony where he will hand me the weapon. The ceremony concludes with the elder announcing our final task.\n\nI shouldn't let the excitement take the better of me, but one thing at a time. We must be patient and calculated as if we were on a hunt.", progress = "Forging a Ka'dani weapon is not an easy feat. A master craftsman must use the very best materials brought by the mentor and trainee.", completion = "<Elder Akazi inspects the Ka'dani spear and nods.>\n\n{name}, you have proven to be a worthy mentor. Ketan deserves this weapon as much as it deserves Ketan.\n\nThe two of you have one more task before this journey comes to an end.", objectives = "Help Al'yaat forge the Ka'dani weapon, then deliver it to Elder Akazi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92885] = { id = 92885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hunter's Prey", description = "The last trial stands before you. Together, you have forged a weapon that will fell any beast, but the weapon is nothing without the hunter.\n\nSince you are not a Ka'dani, I present you with a difficult hunt. Ketan and you will hunt down and slay a prey known to all Har'athir hunters: the great Radooni. The beast ventured too close to Har'athir and should be a suitable hunt.\n\nReturn to me once your hunt is complete and Radooni's sap is on the spear.", completion = "I see now that your presence here and Ketan's perseverance were set by the goddess herself. I am impressed by your actions and resolve. Thanks to you, Ketan's path is clear.", objectives = "Hunt down the great Radooni, then return to Elder Akazi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92890] = { id = 92890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Handful of Voidlight Marl", objectives = "Thank you for your assistance. Please accept these as thanks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92891] = { id = 92891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cluster of Voidlight Marl" }
quests[92892] = { id = 92892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Trove of Voidlight Marl" }
quests[92895] = { id = 92895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hagar's Invitation", description = "Hagar has a message she believes the elves and trolls of Azeroth must all hear. She has sent a call to leaders from the elven and troll tribes to come to Harandar.\n\nI have come here to ask the blood elves to join us, but you should be there as well. You have been with us through so much of this.\n\nThe Rootways from Silvermoon would be the fastest way.", sourceObjective = "Attend Hagar's meeting at the Den in Harandar.", completion = "It should not be long now.", sourceObjectiveStatus = "unverified-source-field" }
quests[92897] = { id = 92897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Preparations Are Complete", description = "{name},\n\nI bear an important message from Hagar. You are invited to a special meeting in Harandar. Please meet me in Silvermoon to discuss it.\n\nOrweyna", sourceObjective = "Speak to Orweyna in Silvermoon City.", completion = "The preparations have been made.", sourceObjectiveStatus = "unverified-source-field" }
quests[92899] = { id = 92899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "History Lesson", description = "Hagar requested that we invite to this meeting all of the troll and elven leaders we know.\n\nIt was not easy to convince them to come. There are some... past grievances between these groups. Hagar hopes to overcome these divisions.\n\nAs we wait for the others to arrive, feel free to speak to the other delegates. The wait is making them restless, so try not to inflame tensions.", sourceObjective = "Speak to the other delegates, then check back in with Orweyna.", completion = "Good to see you again!\n\n<Kinduru looks around the Den, then sighs.>\n\nDo you know where Zul'jan has stomped off to?", sourceObjectiveStatus = "unverified-source-field" }
quests[92900] = { id = 92900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Favor for Kinduru", description = "Zul'jarra could not leave Zul'Aman as the Amani still recover. She sent Zul'jan in her stead.\n\nShe hoped showing trust and giving him dis responsibility would bring him out of her shadow. Make use of his talents. But dis news...\n\nI am an old troll. I have a hard time reining Zul'jan in, but he may listen to you.\n\nWould you join us? Zul'jarra and I would be grateful if Zul'jan stayed out of trouble.", sourceObjective = "Meet up with Zul'jan, Kinduru, and Orweyna in Harandar.", completion = "My patience is dwindling.", sourceObjectiveStatus = "unverified-source-field" }
quests[92901] = { id = 92901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revisionist History", description = "Not all of the visions in this place were clear to us. Some of them were... strange.\n\nOne in particular seemed to revolve around an unfamiliar people: a people that we learned are the Amani trolls.\n\nThe magic used to create the painting, to pull the memories from the past, are tied to the haranir and those close to us. If there was no connection, the Zur'ashar--who create the paintings--could not have recalled troll history.\n\nI can show you and Zul'jan, and you can judge for yourselves.", sourceObjective = "Experience the Amani vision in the Den of Echoes.", completion = "Amani history, painted on the walls of our ancestors. This magic does not work without a bond between our peoples.", sourceObjectiveStatus = "unverified-source-field" }
quests[92902] = { id = 92902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue Amani from Priest Sacrifices" }
quests[92904] = { id = 92904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Zul'Aman", description = "I have heard de story since I was a child! De Amani were outnumbered and still dey fought on! Dey claimed victory through sheer will!\n\nOrweyna says de visions cannot lie. Uncle thinks details of de battle could have been lost. Dey would question everything it means to be Amani.\n\n<Zul'jan scowls.>\n\nI must find de truth of dis. Uncle says if anyone would know, it would be de loa. De loa have said nothing of dis before, but we must start somewhere.\n\nIt's time to go home.", sourceObjective = "Return to Zul'Aman with Zul'jan and Loa Speaker Kinduru.", completion = "Why is my uncle so disorganized?", sourceObjectiveStatus = "unverified-source-field" }
quests[92905] = { id = 92905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help Uncle with Loa", description = "You go find Uncle Kinduru. Uncle doesn't know anything about Ula'tek but can ask the eagle loa. You help him perform a ritual to ask the loa. He says the loa don't know either." }
quests[92906] = { id = 92906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breadcrumb to Eagle Rise" }
quests[92907] = { id = 92907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amani Answers", description = "My uncle has already started communin' with de loa to find information on dis Ula'tek. Meanwhile, we gonna dig through his boxes to see what we can find.\n\n<Zul'jan points to all the boxes scattered around the terrace.>\n\nMy uncle has de biggest collection of histories among de Amani. I used to read through dem when I was a boy.\n\nLook for anything about Ula'tek, snakes, or early Amani history. I'll take these, you search de others.", sourceObjective = "Help Zul'jan search through the boxes for information about Ula'tek.", progress = "What does dis mask know?", completion = "Did you hear what it said? A weapon!", sourceObjectiveStatus = "unverified-source-field" }
quests[92916] = { id = 92916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call for Aid", description = "{name}, I call upon you to aid the Amani again as a fellow hash'ura. Another dire threat is upon them.\n\nMalacrass has returned.\n\nWitherbark Bluffs is under attack by a monstrous enemy the likes of which I have never seen. And with our brush against the Twilight's Blade, the timing could not be worse.\n\nZul'jan deserted us and... we believe he may be at least partially at fault.\n\nWe will deal with both of them in time. For now, help us before we are overrun.", sourceObjective = "Meet with Lady Liadrin in Witherbark Bluff.", completion = "Thank the Light you are here.\n\nWe have work to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[92917] = { id = 92917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Those Bound", description = "<Liadrin wipes sweat from her brow and addresses you without turning. You see minor cuts and scrapes she has neglected to heal.>\n\nWe fell back from the town gates. There were so many wounded and poisoned. Orweyna, Tak'lejo, and I best serve the Amani here.\n\nBut you should be out there helping Zul'jarra.\n\nMalacrass's serpents are capturing Witherbark, coiling around them, and filling them with poison.\n\nFree them--and make sure to find Dak'zor. He was on the front line and first to fall.", sourceObjective = "Rescue 8 Amani villagers and Dak'zor at Witherbark Bluffs.", progress = "Move, {name}! Before we lose more Amani!", completion = "Dey took Dak'zor away to de east?\n\n<Zul'jarra growls.>\n\nToward de strait. Toward de isle. What do dey want with him there?\n\nSpirit or no, I'll find a way to get my hands 'round dat Hex Lord's throat...", sourceObjectiveStatus = "unverified-source-field" }
quests[92919] = { id = 92919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Bark, All Bite", description = "The wounds I have seen... the ferocity.\n\nNot only do these serpents slither on the ground and coil around our warriors' bodies, but they cut deep with their poisoned blades and target them with their talons as they dive from the skies.\n\nZul'jarra and her forces cannot win this on their own, but my hands are needed here. \n\nHelp Zul'jarra by taking them down.", sourceObjective = "Defeat the remaining forces of Malacrass around Witherbark Bluff.", progress = "Never liked snakes... and dis mess is not helpin'.", completion = "De battle is turnin' in our favor thanks to you, but de fight is not done.\n\nWe got some breathin' room now, but we got to strike at de source--Malacrass--before more snakes start crawlin' all over us.", sourceObjectiveStatus = "unverified-source-field" }
quests[92920] = { id = 92920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down With the Skies", description = "I will need some time to call upon Akil'zon and open de way. Dat's where you come in.\n\nProtect me, my hash'ura.\n\nI entrust you with my life. We've taken great leaps before, eh?", sourceObjective = "Defend Zul'jarra while she channels Akil'zon on the Skybridge.", completion = "De loa can't come with us? Then we will have to rely on our own strength.", sourceObjectiveStatus = "unverified-source-field" }
quests[92921] = { id = 92921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Skybridge", description = "<Zul'jarra's face is dark with rage as she looks off toward the Skybridge.>\n\nZul'jan... you let dat snake Malacrass taint your mind and heart. For what? Power?\n\nDe lightwood was one thing. But dis?\n\nI don't know what Malacrass has planned for de captives, but we have to take de fight to him and away from our people.\n\nFollow de monsters' path back to de Skybridge. I will consult de loa and meet you there.\n\nWith their help, we will stop this.", sourceObjective = "Meet Zul'jarra at the Skybridge.", completion = "I will make my way to Malacrass, even if I have to rip de scales off a thousand of these monsters.", sourceObjectiveStatus = "unverified-source-field" }
quests[92922] = { id = 92922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those Who Can't Fight", description = "Zal'jarra also asks us to rescue a few people!", sourceObjective = "Log Description", sourceObjectiveStatus = "unverified-source-field" }
quests[92924] = { id = 92924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Lies Beyond the Fog", description = "With de loa, we are powerful. Without de loa, we are still the Amani. We will get our kin back.\n\nLiadrin will join us soon with reinforcements, and my warriors are eager to take vengeance.\n\nThere can be no delay. For my people's sake and for Zul'jan's.", sourceObjective = "Meet Zul'jarra at Tokka's Landing in the Coiled Isle.", completion = "Dis is de ruins of an Amani town.\n\nIt must be what remains of de settlement here before de bridge fell and de island fell prey to de curse.\n\nBut if even de loa can't come here, how have these tortollans survived? Why are dey here?", sourceObjectiveStatus = "unverified-source-field" }
quests[92925] = { id = 92925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Glint of History", description = "The ruins across this island are ancient, built by the Amani long ago. If we discover how they came to be here, we may learn the truth of Ula'tek.\n\nThen we can show Zul'jan what he is really chasing.\n\nI have an idea of where to look for that crypt. Let us go together, {name}.", sourceObjective = "Follow Orweyna to the main island.", progress = "Goddess willing, we will see a memory of the past.", completion = "The goddess answers us! There must be some lesson to learn in this vision.\n\nLet us learn from the past.", sourceObjectiveStatus = "unverified-source-field" }
quests[92926] = { id = 92926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Astalor's Initiative", description = "Ah, {name}. I am glad to see you here in our city, even if the times are trying.\n\nWe are once again beset on all sides by uncertain friends and dangerous foes, but I am not unprepared. I have a... guest, housed nearby. They may hold the key to our city's survival. \n\nMeet me near the harbor if you have the strength to do what must be done.", completion = "I see your interest has been piqued. \n\nExcellent.", objectives = "Meet Astalor Bloodsworn near the harbor in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92927] = { id = 92927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echoed Steps", description = "Sometimes the goddess' visions are not easy to understand at first, but in time she reveals her intentions.\n\nI will keep the Children of Ula'tek out of your path as you follow her memories.\n\nTrust that she will reveal what we need to learn.\n\nMeet me up ahead once you have witnessed her memories of the Amani.", sourceObjective = "Find three Worldsoul Memories in front of the Path of Whispers.", progress = "These memories... What are we meant to learn from them?", completion = "These must be her remains. She was sealed here and left to die. \n\nBut why?", sourceObjectiveStatus = "unverified-source-field" }
quests[92928] = { id = 92928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Was Buried", description = "The visions of Nek'zali led us here. That we found where she took her last breath is no coincidence.\n\nThere must be something within this crypt that the goddess wishes for us to see.\n\nZul'jarra bid us to find the truth of Ula'tek. Perhaps here we will find the answers we seek.\n\nLet us see where the story we were told in the Den of Echoes ends, and where the truth begins.", sourceObjective = "Investigate three chambers within the Crypt of the Denied.", progress = "The spirits here are unlike Azeroth's memories. What curse binds them to this place?", completion = "I have seen this history before, but something is missing... \n\nWe must search for more.", sourceObjectiveStatus = "unverified-source-field" }
quests[92929] = { id = 92929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lurking in the Dark", description = "Those who built this crypt would not have sealed it without good reason.\n\nA great evil from the past must dwell here.\n\nWe should put to rest any spirits and undead we find. They cannot keep us from the answers we seek.", sourceObjective = "Slay undead and cleanse necrotic energy within the Crypt of the Denied.", progress = "This is a potent evil. It rivals even the Black Blood.", completion = "Whatever the reason they were buried here and whatever reason they have awoken, they deserve to return to the goddess.", sourceObjectiveStatus = "unverified-source-field" }
quests[92930] = { id = 92930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Written by the Victors", description = "A version of this history is written into the Den of Echoes. The same events, only recorded by Amani hands instead of haranir ones. \n\nBut something is missing: Nek'zali. How is she part of the story of Ula'tek? \n\nAnd we do not know how Ula'tek came to this world.\n\nWe must go deeper into the crypt and witness the truth written on its walls.", sourceObjective = "Slay the crypt guardian and witness the final mural.", completion = "Zul'jarra is... ill?\n\nWhat has happened in our absence?", sourceObjectiveStatus = "unverified-source-field" }
quests[92931] = { id = 92931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delay the Venom", description = "The wound from Zul'jan's blade. It won't heal.\n\nZul'jan must have poisoned her. She's weakening, and I have not been successful in curing her with Light.\n\n<Liadrin engulfs Zul'jarra in Light again. Nothing changes.>\n\nBlast it!\n\nWhatever you found in that crypt can wait.\n\nThe Amani are trying to find a cure. Ask Raz'taka if he's made any progress.\n\nIf you need anything else, talk to Tak'lejo. Zul'jarra needs to focus on recovering.", sourceObjective = "Help the others cure Zul'jarra.", progress = "<Orweyna closes her eyes as if listening for something.>", completion = "This troll is with you, {name}? If he wishes to fight the many foes standing between us and the answers we seek, I welcome his aid.", sourceObjectiveStatus = "unverified-source-field" }
quests[92932] = { id = 92932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clear the Swamp", description = "Look in the distance. Restless, evil energy fills the sky. That structure ahead must have the answers we seek.\n\nThe creatures that stand in our way must be culled. We cannot risk being overcome on such a vital mission.", sourceObjective = "Slay 12 swamp beasts in the Whispering Marsh.", progress = "Thin their numbers. I won't risk us being surrounded.", completion = "The beasts are resilient. They must be, to survive in such a place.", sourceObjectiveStatus = "unverified-source-field" }
quests[92933] = { id = 92933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haunted Shore", description = "With Zul'jarra down, de Amani are losin' heart with each passin' moment. We gotta do somethin' to show dem that dis isn't over.\n\nThose tortollans have been helpin' where they can. Let's repay de favor and help out de captain. \n\nSeein' a bunch of their lost crew return to town oughta give dem some hope in dis cursed land.", sourceObjective = "Assist lost tortollans in the Whispering Marsh.", progress = "What is happenin' here?", completion = "The spirits of de swamp possessed de tortollans?\n\nI got more questions than I know what to do with.", sourceObjectiveStatus = "unverified-source-field" }
quests[92934] = { id = 92934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fuel the Calling", description = "<Your loyal follower keeps her voice low as you approach.>\n\nAs you foretold, red rain falls from de sky. De heavens align. A great beast rouses at de door beneath de world. At last, a weapon for de Amani--one greater than any Zandalari loa. We just need de fuel to summon it.\n\nMost of de warband is injured and isolated. Fallen soldiers will welcome de sight of you, expecting you to heal dem.\n\nTake your dagger and do what must be done. Only you can save us, Nek'zali.", sourceObjective = "Betray and sacrifice Injured Hunters found within the Worldsoul Terror.", progress = "<Your loyal follower lowers her head as you approach.>", completion = "Their sacrifice was for de good of the Amani, whether dey knew it or not.", sourceObjectiveStatus = "unverified-source-field" }
quests[92935] = { id = 92935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pushed to the Brink", description = "De ocean at our back slithers with tentacles and eyes, but we are safer there than on dis land. We were fools to think we could claim it from Kith'ix.\n\nI have stood by your new obsession with rituals and superstitions, Nek'zali. Now, I need you to be de healer you once were.\n\nHelp my soldiers fight off de aqir. Buy us the time we need for de transport boats to arrive.", sourceObjective = "Slay aqir within the Worldsoul Terror.", progress = "De promise of an empire was a lie. De Zandalari sent us to our deaths.", completion = "De armies of de aqir are without end. Dey are all around us.\n\nWe fought hard, Nek'zali. But we are out of options.", sourceObjectiveStatus = "unverified-source-field" }
quests[92936] = { id = 92936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Summoning of Ula'tek", description = "Where is de rest of our warband?! De lines are breaking!\n\nMy soldiers will hold dem off as long as dey can. De weak should run. But you and I... if we die, let it be together with weapons in hand, sister.", sourceObjective = "Summon Ula'tek and defeat the aqir.", progress = "Dis is Orweyna's--no, Azeroth's vision? How is dis going to help us cure Zul'jarra?", completion = "De weapon dat saved de Amani. It was a monster created by another monster... to kill a monster!\n\nDat's what our ancestors built their empire on?", sourceObjectiveStatus = "unverified-source-field" }
quests[92937] = { id = 92937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Awakened Evil", description = "Nek'zali, dat priestess... We should bring word of what we've seen back to de hash'ey.\n\nOrweyna. Ay! Wait--what's wrong with her?", sourceObjective = "Check on Orweyna.", completion = "The Fang of Ula'tek. The dagger that Zul'jan wields. We have to find it.", sourceObjectiveStatus = "unverified-source-field" }
quests[92938] = { id = 92938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Site of Terror", description = "The air is thick with restless spirits. But there's more--it is the goddess. Where her voice was once quiet, I can feel it is now raised in anguish. Like a scream of terror.\n\nI fear for what we may find ahead.\n\nI will follow her voice. Come. Together, we uncover her memories of this place.", sourceObjective = "Witness Azeroth's memories across the Altar of Wrath.", progress = "Let us go before her song fades.", completion = "The goddess is calling out in pain. I have never seen her memories in such a state.", sourceObjectiveStatus = "unverified-source-field" }
quests[92939] = { id = 92939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Not Just a Rock!", progress = "Why are these beasts even eating these rocks?", completion = "Yes, you found more rubble!\n\nHave you noticed the runes carved on these rocks emanate Void? Creatures of Voidstorm seem to have an endless hunger for that magic.\n\nSo, I think these beasts are eating the Void in these runes. At least, that makes the most sense.", objectives = "Collect 6 Ancient Rubble from monsters in the Storm Fields.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92944] = { id = 92944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sifting Through Void", description = "There's no rubble on the surface. The beasts are burrowing, so they must be finding it in a cavern underground.\n\nI've been thinking of how to get there.\n\nYou've noticed the vortexes that dot the Storm Fields? They twist space, moving things from place to place.\n\nStep through one and I can reveal the anomalous residue that surrounds them.\n\nCollect the residue and I can make a spell to redirect the portal to where the source of the rubble is!", progress = "I had some suspicion about these runes not being domanaar or ethereal. The specter all but confirms my thoughts. This could be something different. Maybe even a civilization!", completion = "Did you hear that? This world was called Predacea!\n\nWhat a revelation!", objectives = "Jump in the Stellar Vortexes in the Storm Fields and collect 10 Anomalous Residue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92945] = { id = 92945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power of Anguish", description = "These threats we chase are intelligent. Determined. Deadly.\n\nTheir ingenuity will seek to confound you. Their strength will seek to destroy you. It is from their very will to live--to predate--that we will extract the essence required to fuel the magical defenses of our city. \n\nI have had my assistants lay out our friend's toys. You'd do best to familiarize yourself with them.", progress = "Speak with Astalor Bloodsworn to continue.", completion = "One fool's trap is another elf's treasure.", objectives = "Learn how to hunt your prey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92946] = { id = 92946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buried in the Dark", progress = "What more could we learn?", completion = "If this specter and his tablets are to be believed, this world was once thriving with multiple civilizations.\n\nJust like on Azeroth, they fought endless wars. They asked Akintunde for a weapon to end all wars, and he delivered... by making one that ended everything.", objectives = "Jump into the northernmost Stellar Vortex in the Storm Fields and investigate the cave beyond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92948] = { id = 92948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Over My Head", progress = "I sensed no remorse at all from him. How could that be?", completion = "Forgive me, {name}. That all happened so quickly.\n\nWas any of it even true? But what else could that spirit have been?\n\nAn entire world... civilizations that used to thrive right where we stand? Could that really be?\n\nI can tell you only one thing for certain. \n\nThis will haunt me for the rest of my days.", objectives = "Step into the Northernmost Stellar Vortex in the Stormfields to confront Akitunde the Unstoppable.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[92949] = { id = 92949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breadcrumb to Bitterbark" }
quests[92950] = { id = 92950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Collect Ingredients for Uncle" }
quests[92951] = { id = 92951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Digging Deeper", description = "De mask says we are lookin' for de scrolls of Malacrass. While we are in Maisara, try to find any scrolls de Vilebranch have left around.\n\nMaisara is a dangerous place, so don't bother sortin' through dem--just grab 'em and we can check later.\n\nEven if dey don't mention Ula'tek, we might find information about their plans or intentions against de Amani.", sourceObjective = "Collect 8 Vilebranch Scrolls from Maisara Deeps.", progress = "Dis search for Ula'tek is becomin' more dangerous than Zul'jan realizes.", completion = "<Kinduru takes the bundle of scrolls. He says nothing, but is clearly concerned.>", sourceObjectiveStatus = "unverified-source-field" }
quests[92952] = { id = 92952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission to Maisara", description = "De magic helped, but... not enough. I still don't remember my name or past life. Dat knowledge may be lost forever...\n\nI do remember more about Ula'tek--or rather, where we might find more information!\n\nI was forced into dis form by de Vilebranch trolls. Dey kept dark knowledge secret from de other tribes, includin' knowledge of Ula'tek.\n\nIf we are to know more, we must go to de Maisara Deeps.", sourceObjective = "Meet the Enchanted Amani Mask outside Maisara Deeps.", completion = "Malacrass is dead, but dat doesn't mean his knowledge is lost.", sourceObjectiveStatus = "unverified-source-field" }
quests[92953] = { id = 92953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Memories of Malacrass", description = "While I was a servant of de Vilebranch, I remember discussions about Malacrass's research into Ula'tek.\n\nMalacrass recorded his knowledge in scrolls that he kept with him. Now that he's dead, we need to find out what happened to dem.\n\nDe Vilebranch hex masters won't talk willingly... but if you slay dem, I can use their own necromantic magic against dem to compel dem to speak.", sourceObjective = "Eliminate the Vilebranch Hex Masters and interrogate their spirits.", completion = "The Maisara Caverns are even more dangerous than de Deeps, and Vordaza is as deadly as she is cruel.", sourceObjectiveStatus = "unverified-source-field" }
quests[92954] = { id = 92954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maisara Caverns: Master of Souls", description = "Malacrass's notes are with Vordaza, and she's using them to further her necromantic experiments.\n\nI need you to go into de Maisara Caverns to recover them. It will be dangerous, and you will need to gather allies before venturing in.\n\nI will stay here and protect my uncle. We need to sort through all de scrolls we gathered and see what else we can find out.", sourceObjective = "Collect Malacrass's Notes from Vordaza and complete the Maisara Caverns dungeon.", progress = "Will Malacrass's notes hold de next clue? Or is dis all just a waste of time?", completion = "You got dem. Now let's see if dis was worth all de effort.\n\n<Zul'jan flips through the scrolls.>", sourceObjectiveStatus = "unverified-source-field" }
quests[92955] = { id = 92955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tablets of Numazon", description = "De ancestors did not bow to a loa--dey claimed a weapon! A weapon dat led to our victory.\n\nI must know more.\n\nYou said de tablets at Numazon are de oldest in Zul'Aman. We can continue de search there. Perhaps de ancient Amani left behind clues for us.\n\nUncle says we should bring de mask. A stray memory might be de key to unlocking dis mystery.", sourceObjective = "Meet Zul'jan outside Numazon.", completion = "Uncle does not understand. Ula'tek could change everything.", sourceObjectiveStatus = "unverified-source-field" }
quests[92957] = { id = 92957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There's the Rub", description = "If de tablets were made when de Amani first arrived in Zul'Aman, den there must be some clue about Ula'tek here.\n\nDe tablets are too heavy to carry, so Uncle suggested dat we take rubbings of de inscriptions.\n\nI scouted ahead and gathered a few, but I ran into de Vilebranch. I came back here to make sure Uncle was safe.\n\nEnter Numazon and collect more of de rubbings while I watch over Uncle. Watch out for de Vilebranch.", sourceObjective = "Take 6 rubbings of the Ancient Amani Tablets within Numazon.", progress = "Let me take a look at the rubbings...", completion = "Look here! Dis mentions the Amani summoning a great serpent to save dem from a terrible foe.\n\nAnd here, de serpent was victorious but de Amani sealed it away.\n\nDe first shrine built in Atal'Aman was dedicated to the serpent.\n\n<Kinduru continues to analyze the rubbings.>", sourceObjectiveStatus = "unverified-source-field" }
quests[92958] = { id = 92958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brain Drain", description = "I wish I could be more help but... de gaps in my memory. Due to de damage de mask has sustained, dat magic has leaked out for who knows how long.\n\nYou repaired de physical parts of de mask, but de magic within is still weak.\n\nZul'jan says Vilebranch trolls occupy this crypt. De magic dat binds me together is like de magic they use.\n\nYou might be able to help. Retrieve their hex fetishes--I should be able to drain the magic from them.", sourceObjective = "Collect 6 Vilebranch Hex Fetishes from the Vilebranch trolls in Numazon.", progress = "De magic of the Vilebranch feels so familiar... Did dey put me in this mask?", completion = "It will just take a moment to drain de magic from de fetishes.", sourceObjectiveStatus = "unverified-source-field" }
quests[92961] = { id = 92961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nSentinel of stone.\nFirst to greet each new neighbor.\nSeek out the deep shade.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
