quests[93002] = { id = 93002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nWhere roses are red.\nThe perfect venue awaits.\nThrow some rice, then dig.\n\nGood luck!", progress = "You found the treasure!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93003] = { id = 93003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nArcane power thrums.\nJourney home with a mere step.\nDig beside the roost.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93004] = { id = 93004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nWhere trees have no roots.\nA gate has no door or hinge.\nWill call for treasure.\n\nGood luck!", progress = "You found the treasure!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93005] = { id = 93005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nMushrooms mark the ring.\nDeep within the shadowed wood.\nDig where fireflies swarm.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93006] = { id = 93006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nEarth, fire, smoke, and steam.\nBlade or plow, the shaper's choice.\nLook where metals bend.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93007] = { id = 93007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nAzure and gold sway.\nWhile beneath pretenders play.\nInvestigate stage left.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93008] = { id = 93008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nSix sides, but no walls.\nAfloat above chill waters.\nSecrets wait below.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93009] = { id = 93009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nSeek the smallest house.\nWhere pawsteps mark the sand.\nNow dig where dogs lie.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93010] = { id = 93010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Serpent Shrine", description = "Here! De note says Ula'tek was sealed away by de Amani. To break de seal, one needs a \"key.\"\n\n<Zul'jan flips through the notes.>\n\nDe key was hidden within a shrine and protected with ancient magic. But which shrine... \n\n<Zul'jan looks up.>\n\nDidn't de tablets at Numazon mention a shrine bein' \"dedicated to de serpent's victory?\" We know from de visions in Harandar dat Ula'tek was a serpent. \n\nDat must be it! De key is hidden at de serpent shrine in Atal'Aman!", sourceObjective = "Meet Zul'jan at the Warlord's Stair within Atal'Aman.", completion = "Dis shrine is ancient. Small. Unremarkable.\n\nDe perfect hiding place.", sourceObjectiveStatus = "unverified-source-field" }
quests[93011] = { id = 93011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legacy of the Amani", description = "If Malacrass was right, de key to Ula'tek should be right here.\n\n<Zul'jan's heavy hammer thumps onto the shrine for emphasis.>\n\nIt may take me some time to break through de stone to find it.\n\nI don't know what kind of protection de ancestors have in place, but you will have to deal with dem while I work.\n\nI admit, I did not believe de visions in Harandar. I don't fully trust Malacrass's notes either.\n\nBut if de key is here, dat would be undeniable proof dat what we are chasing is real.", sourceObjective = "Protect Zul'jan as he dismantles the serpent shrine.", completion = "The Amani found you and Kinduru at Atal'Aman. They carried you back here.", sourceObjectiveStatus = "unverified-source-field" }
quests[93012] = { id = 93012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dead End", description = "After the meeting in Harandar, I came here to speak with Zul'jarra about the vision you witnessed. Zul'jan had seemed upset when you left and it was not my intent to make him so.\n\nBut all of that can wait. Now that you're awake, you should go speak to Zul'jarra. She wants to know what happened at Atal'Aman.", sourceObjective = "Speak to Zul'jarra at Amani'Zar Village.", progress = "How could this have happened?", completion = "I have already sent scouts to search for Zul'jan, but it will be impossible to cover so much ground. I pray he sees through de lies dat Malacrass has woven before it's too late.\n\n<Zul'jarra's expression is grim, then softens as a small eagle lands on your shoulder.>\n\nThank you, {name}, for telling me what happened and for being with my uncle at de end.\n\nDis eagle was my uncle's favorite companion on his walks through Zul'Aman. I think he would like it if you took care of him now dat he's gone.", sourceObjectiveStatus = "unverified-source-field" }
quests[93013] = { id = 93013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: Push Back the Light" }
quests[93018] = { id = 93018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Them That Were Lost", description = "My brother is here. And so are de captives.\n\nDey are bein' held in de small shrines ahead. For what, I don't know.\n\nBut somehow my brother is involved.\n\nGettin' my people free of dis place is of de highest priority. Do whatever is necessary to free dem.\n\nZul'jan can wait until de prisoners are safe.", sourceObjective = "Release the Amani prisoners.", progress = "I will fight for dem until dey are free.", completion = "My brother has much to answer for. His path is growin' darker with each step he takes.\n\nWhether he knew about their capture and torture, or was just lettin' it happen, it is clear I need to knock some sense into him.", sourceObjectiveStatus = "unverified-source-field" }
quests[93019] = { id = 93019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Situation Normal, All Snaked Up", description = "<Zul'jarra's hand tightens on her axe.>\n\nWe knew de island was cursed, but is dis de curse? Or has what Zul'jan and Malacrass done brought dem here?\n\nDe answer doesn't matter. We must find and save de ones dey kidnapped--and find my brother.\n\n<Zul'jarra surveys the island stretching out around her. Her eyes narrow.>\n\nI see somethin' ahead. A structure. I'm gonna see if my people are there.\n\nYou protect de people here. Crush de serpents. Grind dem into de ground.\n\nMeet me when you are done.", sourceObjective = "Slay the Children of Ula'tek in the Serpent's Tail.", progress = "Nobody's gonna be safe until dey are all dead.", completion = "<Zul'jarra's eyes are locked on the figure of her brother. \n\nYou expect bright fury to be in her eyes, but all you see is dull sadness.>", sourceObjectiveStatus = "unverified-source-field" }
quests[93022] = { id = 93022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire, the Only Way to Be Sure", description = "De prisoners need to be rescued, yes, but dis place is an abomination.\n\nWe must cleanse it with de spirit-born fire of Jan'alai.\n\nTake dis totem. It will allow you to wield de breath of our loa.\n\nPurge their nests. And kill de spiteful broodsisters that laid dem!", sourceObjective = "Use the Breath of Jan'alai to clear the Blistering Terrace.", progress = "Did you fry de eggs and de hens dat laid dem?", completion = "Praise dat Jan'alai found us worthy of our blessin'.\n\nPraise dat de hash'ey's will has been done!", sourceObjectiveStatus = "unverified-source-field" }
quests[93023] = { id = 93023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death of Furies", description = "Now only these creatures block our way to...\n\n<Zul'jarra growls softly.>\n\n...to Zul'jan.\n\nDey are protectin' him like he's one of dem. One of their army.\n\nWhether he is or not, we gotta take dem down if we're gonna find out.", sourceObjective = "Defeat the Brood Furies.", completion = "That dagger... that power...\n\nWhat is he doin'?\n\nWe have to talk him down.", sourceObjectiveStatus = "unverified-source-field" }
quests[93024] = { id = 93024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Come With Me", description = "Stay here, hash'ura. I'm goin' in to talk to him.\n\nMaybe I can talk him into leavin' on his own--and tellin' us what Malacrass has planned.\n\nI hope to de loa that he will come to his senses.", sourceObjective = "Confront Zul'jan.", completion = "Does Lor'themar not see? We will face the tide of these monsters next should the Amani fall.\n\nOur status as hash'uras aside, {name}, I refuse to stand by and let that happen.", sourceObjectiveStatus = "unverified-source-field" }
quests[93025] = { id = 93025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words 9" }
quests[93043] = { id = 93043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Predator Becomes Prey", progress = "Speak with Astalor Bloodsworn to continue.", completion = "I can assure you that it will seldom be this easy.", objectives = "Survive an ambush by your prey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93046] = { id = 93046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nestled Belongings" }
quests[93047] = { id = 93047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Butchery Basics", description = "We can't keep up with how much these soldiers eat. Lend us just a bit of your time to feed dis army, hm?\n\nWe need boar. Not just a steak or two, we need de entire boar. Nothin' goes to waste, yah?", progress = "De art of Amani huntin' is about discipline. You practice until de skills come as naturally as breathin'.\n\nBut right now, discipline means doin' what I tell you.", completion = "You are an impressive hunter, dat is for sure. Thank you for helpin' us out here.", objectives = "Collect 10 Boar Carcasses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93048] = { id = 93048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Got No Rhythm", description = "Dat boy Kovu stormed out of here without even tryin' a single step. He thinks he's got two left feet, but he isn't even willin' to try.\n\nYou look like an impressive fighter. He'll respect you for dat.\n\nMaybe he just needs de right dance partner to show him de steps. Help him out, hm?", progress = "Makin' progress, yah?", completion = "Dat boy still needs a lot of practice, but you helped him get out of his head and just feel de rhythm.", objectives = "Teach Kovu how to dance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93049] = { id = 93049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Homework Support", description = "<The little girl keeps her voice low, making sure her father doesn't overhear.>\n\nMy friends are goin' out to play down where de shade lilies grow, but I'm supposed to do a buncha borin' apothecary stuff.\n\nPapa wants me to collect some plants to make salves and balms we use for healin'. I asked if it could wait and he said no.\n\nWhat if... you helped me out? Just dis once, pleeease?", progress = "Did you get all of dem?", completion = "All in perfect condition!\n\nMaybe you should be de apprentice instead.", objectives = "Collect 15 Pristine Shade Lilies and 8 Dragonhawk Fern Fronds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93050] = { id = 93050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Altar History", description = "De altars need to be infused with de power of de loas every so often.\n\nI'm not as spry as I used to be and de altars are all spread out.\n\nHelp an old shaman out, eh? I'll give you my totem to channel de loas' power into de altars.\n\nAnd maybe you can learn a thing or two from de other acolytes and myself in de process.", progress = "I just need to take a little breather here.\n\nDon't go worryin' about me, now. Keep focused on the task at hand, eh?", completion = "My days of combat are behind me, but I'm glad to be helpin' out around de village.", objectives = "Empower the 4 Loa Altars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93051] = { id = 93051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Exam", description = "My trainin' is almost complete!\n\nMy commander says I need to prove myself against a strong fighter before she can recommend me for combat.\n\nBut I've been strugglin' to find someone willin' to spar with me after... uh, after what happened de last time...\n\nYou look capable. And intimidatin'. Mind helpin' me out here?\n\nAnd no goin' easy on me, yes? I can take it.", progress = "Do not pull even a single punch. De boy must succeed or fail on his own.\n\nIf he's not ready, you will be doin' him no favors sendin' him into the fray unprepared.", completion = "You fought well.\n\nYour own strength proved Dar'rak can hold his own against warriors far stronger than himself.\n\nI never expected him to beat you, {name}. But de fact that he still breathes is an impressive enough feat, hm?", objectives = "Spar Dar'rak for his final exam.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93053] = { id = 93053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleaning the Den" }
quests[93055] = { id = 93055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extracurriculars", progress = "Back so soon? Perhaps I miscalculated how long you would spend procrastinating.", completion = "Hopefully this diversion has been enlightening.", objectives = "Speak with Khadgar in Dalaran and Eternus at the Infinite Bazaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93056] = { id = 93056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson in Alacrity", completion = "Yes, now you are prepared.", objectives = "Reach level 70.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93057] = { id = 93057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A House For You", description = "<A glowing parchment appears in front of you with the symbol of a home in front of it.>\n\nGreetings, {name}!\n\nHave you ever wanted to own a home? Have a place to call your own? Now you can!\n\nJoin us in Founder's Point, the new Housing Neighborhood. Get your very own slice of Azeroth!This quest line will unlock:", objectives = "Travel to your capital city's portal room to find a portal to a neighborhood.\n\nYou can also travel to a housing neighborhood from the housing Dashboard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93063] = { id = 93063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Spears", description = "De spirits, their weapons--I recognize dem! Dey are Amani: heroes and warriors from our murals and stories! Dis was de site of a great battle--one dat earned us de right to call dis land Zul'Aman. \n\nWe should bring evidence of our history back to the others watchin' Zul'jarra, to remind 'em we got our ancestors watchin' over us.\n\nTakin' de raised spirits' weapons may \"raise some spirits\" back at camp, no?", sourceObjective = "Collect 12 ancient weaponry from troll spirits in the Altar of Wrath.", progress = "Jokin' aside, what haunts these warriors? \n\nShouldn't dey be at rest?", completion = "So many dead. De foe we faced must have been mighty. \n\nYet we conquered it together!", sourceObjectiveStatus = "unverified-source-field" }
quests[93064] = { id = 93064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Awe of She", description = "It's the priestess again--the one whose remains we found in the crypt.\n\nThese memories--no. Not memories. They are like nightmares. Something horrible befell the goddess. We must see it directly. Hear her song through all the noise.\n\nI fear this vision will be too much for me alone. Join me, both of you, and let us witness the goddess' past terror.", sourceObjective = "Witness the Worldsoul Terror with Orweyna.", completion = "The Zandalari sent us to die.\n\nKnowing it changes nothing. We make our stand against de aqir, or we fall.", sourceObjectiveStatus = "unverified-source-field" }
quests[93071] = { id = 93071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rotten to the Core" }
quests[93073] = { id = 93073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nBetween mighty tusks.\nA doorway shimmers and hums.\nLook where the carts park.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93074] = { id = 93074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nTwo towers stand guard.\nWorn bridge spans the falls below.\nGo smell some flowers.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93075] = { id = 93075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nThough it may have leaks.\nWooden wall diverts the stream.\nCheck the ledge below.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
