quests[93080] = { id = 93080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nMist threads through the pines.\nSellers ring the roundabout.\nSearch the succulents.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93081] = { id = 93081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nFrom sagging rope bridge.\nTorches mark a steep descent.\nSearch the water's edge.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93082] = { id = 93082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nCedar scents the air.\nWhere kneaded muscles soak deep.\nSearch between the tubs.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93083] = { id = 93083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nPlatform high above.\nAt the edge of sea and wood.\nLook where the lights sway.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93084] = { id = 93084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nThrough an arch of bone.\nA stream cradles what once moved.\nSearch the vertebrae.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93085] = { id = 93085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nNear the scorching songs.\nArbor frames the setting sun.\nDig beyond the vows.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93086] = { id = 93086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Sanctum!", completion = "Let us begin.", objectives = "Return to Astalor's Sanctum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93087] = { id = 93087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nBelow the towers.\nTownsfolk guarded from the spray.\nDig in awning's shade.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93088] = { id = 93088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nBelow forest deck.\nSecret straw-floored writer's nook.\nSeek the wheelbarrow.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93091] = { id = 93091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nDeep in the forest.\nWhere the hookah haze rises.\nTreasure waits below.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93093] = { id = 93093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnarldin Trophies", description = "I was sent here to prove dat I am ready to be an Amani warrior. All dat want de honor must prove demselves.\n\nI chose de gnarldin since dey are close now, and I heard Zul'jarra softened dem up a little.\n\nLooks like I wasn't de only one who thought dat and was wrong.\n\nBut I still need to collect as many trophies from de gnarldin as possible.\n\nIf I have de bigshot hash'ura helpin' me, there's no way I can lose, no?\n\nYou get de trophies. I will stay behind to watch our backs.", progress = "Did you get de trophies? De gnarldin have plenty of dem from all their fightin'.", completion = "Dat... dat is a lot of trophies there, hash'ura.", objectives = "Recover 35 trophies from gnarldin and their allies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93094] = { id = 93094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scavenged Victory", description = "Many warriors have chosen to face de gnarldin since dey came to Zul'Aman, but many have failed.\n\nDey thought now dat de gnarldin are in our territory and weakened, dey would be easier...\n\nDe gnarldin hunters have collected tablets from de Amani hunters dat fell here.\n\nBut with you at my side, we can get \"vengeance\" for those dat lost their lives here--no killin' or life riskin' required.\n\nWe don't have to kill de gnarldin. We just have to get close enough to gather de tablets. What do you say?", progress = "With those tablets, no one can question our strength!", completion = "Dis is plenty!\n\nAll of dem were actually dead... right?", objectives = "Recover 6 Hunter's Tablets from fallen Amani.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93095] = { id = 93095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bitter Fury", description = "De leader of de gnarldin here is known as Tusk Taker. Take a wild guess why she's named dat.\n\nThere is a trophy dis one has in a cave. Take it, and she will run out rarin' for a fight.\n\nDefeat her for me, and no one can challenge my right to be an Amani warrior.", progress = "Did you kill Tusk Taker yet?", completion = "Hah! Tusk Taker is dead!\n\nDe others will see me as a true Amani warrior now--when I tell them I took all de trophies that killed Tusk Taker.", objectives = "Steal Tusk Taker's Taken Tusk Trophy to lure her out, then defeat her.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93096] = { id = 93096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amani Honor", description = "Dat is all de trophies we need.\n\nI'll take dem to de meetin' point nearby. All we gotta do is wait there for Huntmaster Jinki to show up.\n\nCome!", completion = "Dis is a shameful fate for Kel'vujo, but one dat he chose.\n\nYou, hash'ura, have proven once again to be strong. \n\nTake dis as thanks for helpin' to weed out de weak and unfit from our warriors.", objectives = "Meet Kel'vujo at the meeting point to receive your reward from Huntmaster Jinki.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93097] = { id = 93097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nWhere the desert blooms.\nFire burns at circle's center.\nLook to the shadows.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
